//! `WP_Theme_JSON_Resolver`; every expected value was produced by WordPress 7.1.5's resolver over the same themes.
//!
//! Generated by `.superpowers/gen_resolver.py`; edit the generator, not the cases.

#![allow(unused_variables)]

mod support;

use std::cell::{Cell, RefCell};
use std::rc::Rc;

use speedyspec_hooks::Value;
use speedyspec_wp_theme_json::resolver::{ResolverDeps, ThemeJsonResolver};
use speedyspec_wp_theme_json::{
    MemoryActiveTheme, MemoryBlockMetadata, MemoryGlobalStylesPosts, MemoryVariationRegistrar,
    NoTranslation, RecordedDiagnostics, ThemeJsonApi, ThemeJsonCodec, ThemeJsonDeps,
};
use speedyspec_wp_theme_json_contracts::ports::{FilteredLayer, LayerFilters};
use speedyspec_wp_theme_json_contracts::{Origin, ThemeJsonError};
use support::core_blocks::core_blocks;
use support::{AsciiText, assert_php_same as assert_php_eq, json, php_list, safe_css};

fn dir() -> String {
    format!("{}/tests/data/themedir1", env!("CARGO_MANIFEST_DIR"))
}

/// A recorded expectation with this checkout's fixture folder where it says `{themedir1}`.
///
/// WordPress's decode notice names the file by its absolute path, so the recording cannot hold one.
fn in_dir(expected: &str) -> String {
    expected.replace("{themedir1}", &dir())
}

/// The data filters a case sets: an `update_with` on the theme layer, and call counters.
#[derive(Default)]
struct Filters {
    api: RefCell<Option<Rc<ThemeJsonApi>>>,
    theme_update: RefCell<Option<Value>>,
    count_default: Cell<bool>,
    count_theme: Cell<bool>,
    default_calls: Cell<i64>,
    theme_calls: Cell<i64>,
}

impl LayerFilters for Filters {
    fn apply(
        &self,
        hook: &str,
        origin: Origin,
        config: Value,
    ) -> Result<FilteredLayer, ThemeJsonError> {
        if hook == "wp_theme_json_data_default" && self.count_default.get() {
            self.default_calls.set(self.default_calls.get() + 1);
        }
        if hook == "wp_theme_json_data_theme" && self.count_theme.get() {
            self.theme_calls.set(self.theme_calls.get() + 1);
        }
        if hook == "wp_theme_json_data_theme"
            && let Some(update) = self.theme_update.borrow().clone()
        {
            let api = self.api.borrow().clone().expect("api");
            let base = api.construct(config, b"theme");
            let incoming = api.construct(update, b"theme");
            return Ok(FilteredLayer::Built(
                api.get_raw_data(&api.merge(&base, &incoming)),
            ));
        }
        Ok(FilteredLayer::Config(config))
    }
}

struct Harness {
    theme: Rc<MemoryActiveTheme>,
    posts: Rc<MemoryGlobalStylesPosts>,
    blocks: Rc<MemoryBlockMetadata>,
    notices: Rc<RecordedDiagnostics>,
    filters: Rc<Filters>,
    resolver: ThemeJsonResolver,
}

impl Harness {
    fn new(theme_dir: &str, template_dir: Option<&str>, classic: Value) -> Harness {
        let blocks = Rc::new(MemoryBlockMetadata::new());
        for b in core_blocks() {
            blocks.register(b);
        }
        for (block, style) in [("core/group", "section-a"), ("core/quote", "fancy")] {
            blocks.register_style(
                block,
                json(&format!(r#"{{"name":"{style}","label":"{style}"}}"#)),
            );
        }
        let notices = Rc::new(RecordedDiagnostics::default());
        let deps = ThemeJsonDeps::new(
            blocks.clone(),
            Rc::new(AsciiText),
            Rc::new(NoTranslation),
            notices.clone(),
            safe_css(),
        );
        let api = Rc::new(ThemeJsonApi::new(deps));
        let theme = Rc::new(MemoryActiveTheme::new(theme_dir, template_dir));
        *theme.classic_settings.borrow_mut() = classic;
        let posts = Rc::new(MemoryGlobalStylesPosts::default());
        let filters = Rc::new(Filters::default());
        *filters.api.borrow_mut() = Some(api.clone());
        let resolver = ThemeJsonResolver::new(
            api,
            ResolverDeps {
                theme: theme.clone(),
                filters: filters.clone(),
                posts: posts.clone(),
                registrar: Rc::new(MemoryVariationRegistrar(blocks.clone())),
                core_dir: format!("{}/tests/data/core", env!("CARGO_MANIFEST_DIR")),
            },
        );
        Harness {
            theme,
            posts,
            blocks,
            notices,
            filters,
            resolver,
        }
    }
    fn resolver(&self) -> &ThemeJsonResolver {
        &self.resolver
    }
    fn notices(&self) -> Vec<String> {
        self.notices.notices.borrow().clone()
    }
    fn filter_theme_update(&self, update: &str) {
        *self.filters.theme_update.borrow_mut() = Some(json(update));
    }
    fn count_default(&self) {
        self.filters.count_default.set(true);
    }
    fn count_theme(&self) {
        self.filters.count_theme.set(true);
    }
    fn default_calls(&self) -> i64 {
        self.filters.default_calls.get()
    }
    fn theme_calls(&self) -> i64 {
        self.filters.theme_calls.get()
    }
}

fn pair(data: Value, notices: Vec<String>) -> Value {
    let _ = ThemeJsonCodec::encode;
    php_list(vec![
        data,
        php_list(notices.into_iter().map(Value::Str).collect()),
    ])
}

