#[test]
fn user_post_id_creates_post() {
    let actual = {
        let h = Harness::new(
            &format!("{}/block-theme", dir()),
            None,
            json(
                r##"{"disableCustomColors":false,"disableCustomFontSizes":false,"disableCustomGradients":false,"disableLayoutStyles":false,"enableCustomLineHeight":false,"enableCustomSpacing":false,"enableCustomUnits":false}"##,
            ),
        );
        let r = h.resolver();
        h.notices.notices.borrow_mut().clear();
        let v: Value = {
            php_list(vec![
                r.get_user_global_styles_post_id(),
                r.get_user_global_styles_post_id(),
                speedyspec_wp_theme_json::array_path::get(
                    &r.get_user_data_from_wp_global_styles(None, false, &json(r#"["publish"]"#)),
                    &["post_content"],
                )
                .cloned()
                .unwrap_or(Value::Null),
            ])
        };
        pair(v, h.notices())
    };
    assert_php_eq(
        &actual,
        &json(r##"[[100,100,"{\"version\": 3, \"isGlobalStylesUserThemeJSON\": true }"],[]]"##),
    );
}

