#[test]
fn core_data_recomputed_once_when_blocks_change() {
    let actual = {
        let h = Harness::new(
            &format!("{}/block-theme", dir()),
            None,
            json(
                r##"{"disableCustomColors":false,"disableCustomFontSizes":false,"disableCustomGradients":false,"disableLayoutStyles":false,"enableCustomLineHeight":false,"enableCustomSpacing":false,"enableCustomUnits":false}"##,
            ),
        );
        let r = h.resolver();
        h.notices.notices.borrow_mut().clear();
        let v: Value = {
            h.count_default();
            for _ in 0..3 {
                r.get_core_data().unwrap();
            }
            h.blocks
                .register(speedyspec_wp_theme_json_contracts::ports::RegisteredBlock {
                    name: "test/late".into(),
                    selectors: Value::Array(Vec::new()),
                    supports: Value::Null,
                    style_names: vec![],
                });
            for _ in 0..2 {
                r.get_core_data().unwrap();
            }
            Value::Int(h.default_calls())
        };
        pair(v, h.notices())
    };
    assert_php_eq(&actual, &json(r##"[3,[]]"##));
}

#[test]
fn clean_cached_data_rereads() {
    let actual = {
        let h = Harness::new(
            &format!("{}/block-theme", dir()),
            None,
            json(
                r##"{"disableCustomColors":false,"disableCustomFontSizes":false,"disableCustomGradients":false,"disableLayoutStyles":false,"enableCustomLineHeight":false,"enableCustomSpacing":false,"enableCustomUnits":false}"##,
            ),
        );
        let r = h.resolver();
        h.notices.notices.borrow_mut().clear();
        let v: Value = {
            h.count_theme();
            for _ in 0..3 {
                r.get_theme_data(&Value::Array(Vec::new()), true).unwrap();
            }
            r.clean_cached_data();
            r.get_theme_data(&Value::Array(Vec::new()), true).unwrap();
            Value::Int(h.theme_calls())
        };
        pair(v, h.notices())
    };
    assert_php_eq(&actual, &json(r##"[3,[]]"##));
}
